DROP TABLE IF EXISTS G20_Joueur ;
DROP TABLE IF EXISTS G20_Equipe ;

CREATE TABLE G20_Equipe (
    id_equipe SERIAL PRIMARY KEY, 
    nom_equipe VARCHAR(100) NOT NULL,
    ville VARCHAR(100) NOT NULL
);


CREATE TABLE G20_Joueur (
    id_joueur SERIAL PRIMARY KEY,  
    nom_joueur VARCHAR(100) NOT NULL,
    jou_nationalite VARCHAR(50) NOT NULL,
    jou_taille INT NOT NULL,
    jou_poids INT NOT NULL,
    jou_poste VARCHAR(100) NOT NULL CHECK (jou_poste IN ('Pilier', 'Talonneur', '2ème ligne', '3ème ligne', 'Mêlée', 'Ouverture', 'Centre', 'Ailier', 'Arrière')),
    id_equipe INT,
    FOREIGN KEY (id_equipe) REFERENCES G20_Equipe(id_equipe)
);

